#include <iostream>

int main() {
    // 1. Guard region: any throw inside is candidate for catch below
    try {
        for (int tr = 0; tr < 10; ++tr) {
            // 2. Signal error condition (string literal as exception value)
            if (tr == 5) throw "Reached 5";
        }
    }
    // 3. Match on exact type (const char*) -- promotion rules do NOT apply
    catch (const char* msg) {
        std::cout << "Error: " << msg;
    }
    return 0;
}

// Sketch of the standard class
class exception {
public:
    virtual const char* what() const throw();
};

#include <exception>

// 1. Derive from the standard exception base
struct DivisionBy0 : public std::exception {
    int value;
    DivisionBy0(int v) : value(v) {}
    // 2. Override what() to return a domain-specific message
    const char* what() const noexcept override {
        return "Division by zero";
    }
};

// 3. Throw at the error site, carry context (value) for the catch
double divide(int a, int b) {
    if (b == 0) throw DivisionBy0(a);
    return a / (double)b;
}

// 1. Specifier on a declaration: promise about throw behavior
int compute(int x) noexcept;            // never throws
int risky(int x)   noexcept(false);     // may throw (explicit)

// 2. Operator on an expression: compile-time query about throw behavior
static_assert(noexcept(compute(0)));    // ok
static_assert(!noexcept(risky(0)));     // ok

#include <iostream>
#include <new>   // for std::nothrow

int main() {
    int* x = new (std::nothrow) int[1000000000000];
    if (x == nullptr) {
        std::cout << "Unable to allocate memory!";
        return 1;
    }
    delete[] x;
    return 0;
}

#include <utility>   // std::swap

class Buffer {
    int*   data_;
    size_t size_;
public:
    // 1. swap is noexcept -- the nothrow primitive we build strong guarantees on
    friend void swap(Buffer& a, Buffer& b) noexcept {
        std::swap(a.data_, b.data_);
        std::swap(a.size_, b.size_);
    }

    // 2. copy-and-swap assignment: STRONG guarantee
    Buffer& operator=(const Buffer& other) {
        Buffer tmp(other);   // may throw -- *this is still untouched
        swap(*this, tmp);    // noexcept -- commit point
        return *this;
    }

    // 3. Move constructor noexcept -- enables vector to use move on resize
    Buffer(Buffer&& src) noexcept
        : data_(src.data_), size_(src.size_) {
        src.data_ = nullptr;
        src.size_ = 0;
    }

    // 4. Destructor noexcept by default -- the floor every RAII type provides
    ~Buffer() { delete[] data_; }
};

