// fs:[0] is offset 0 of the Thread Information Block (TIB) -- head of the per-thread SEH chain
// 1. Link new record to current head (push to chain)
new_record.next         = fs:[0];
// 2. Install handler pointer
new_record.handler      = &__except_filter;
// 3. Point TIB at new record (atomic enough on this thread)
fs:[0]                  = &new_record;

// 4. On clean exit: unlink (pop from chain)
fs:[0]                  = new_record.next;

#include <memory>
#include <fstream>
#include <mutex>

std::mutex g_mtx;

void processFile(const char* path) {
    // 1. Acquire lock (RAII -- released at scope exit)
    std::lock_guard<std::mutex> lock(g_mtx);
    // 2. Open file (RAII -- closed at scope exit)
    std::ifstream in(path);
    // 3. Allocate work buffer (RAII -- freed at scope exit)
    auto buf = std::make_unique<char[]>(4096);
    // 4. Do work -- exceptions now safe; locals unwind in reverse
    if (!in) throw std::runtime_error("open failed");
    // ... work that may throw ...
}
// Order of destruction (reverse of construction): buf, in, lock
